<script>
let stats={},bookings=[],cottages=[],customers=[],profile=null,currentChartPeriod='week',selectedChartMonth=new Date().getMonth(),currentReportPeriod='day',selectedReportMonth=new Date().getMonth(),updatingCottageId=null;const colors={Small:'#009688',Medium:'#4db6ac',Large:'#1e847f',Family:'#7ad3ca'};
function money(v){return'PHP '+Number(v||0).toLocaleString()}function openModal(id){document.getElementById(id+'-modal').classList.add('active')}function closeModal(id){document.getElementById(id+'-modal').classList.remove('active')}function formatDate(v){if(!v)return'N/A';const d=new Date(v);return d.toLocaleDateString('en-PH',{year:'numeric',month:'short',day:'numeric'})}function guestName(b){return b.guest_name||b.customer_name||'Guest'}function guestEmail(b){return b.guest_email||b.customer_email||'N/A'}
function showPage(page){document.querySelectorAll('.page').forEach(p=>p.classList.remove('active'));document.querySelectorAll('.nav button').forEach(b=>b.classList.remove('active'));document.getElementById('page-'+page).classList.add('active');document.getElementById('nav-'+page).classList.add('active');const titles={dashboard:['Admin Dashboard','Overview of your resort reservation system'],reservations:['Reservations','Manage live reservations and walk-in bookings'],customers:['Customer Accounts','Search and manage customer accounts'],cottages:['Cottages','Add cottages and update rates'],reports:['Reports','View booking summaries by day, week, or month'],settings:['Settings','Admin profile and password settings']};document.getElementById('page-title').textContent=titles[page][0];document.getElementById('page-subtitle').textContent=titles[page][1];if(page==='reports')renderReports();if(page==='customers')renderCustomers();if(page==='reservations')renderReservations()}
function whenBooked(b){return new Date(b.booked_on||b.created_at||b.check_in)}
function chartRange(){const now=new Date(),today=new Date(now.getFullYear(),now.getMonth(),now.getDate());let s=new Date(today),e=new Date(today.getFullYear(),today.getMonth(),today.getDate(),23,59,59,999),label='Weekly chart view';if(currentChartPeriod==='week'){const day=today.getDay(),diff=day===0?6:day-1;s.setDate(today.getDate()-diff);e=new Date(s.getFullYear(),s.getMonth(),s.getDate()+6,23,59,59,999);label=`Weekly chart view: ${formatDate(s)} - ${formatDate(e)}`}else{s=new Date(today.getFullYear(),selectedChartMonth,1);e=new Date(today.getFullYear(),selectedChartMonth+1,0,23,59,59,999);label=`Monthly chart view: ${s.toLocaleDateString('en-PH',{month:'long',year:'numeric'})}`}return{s,e,label}}
function reportRange(){const now=new Date(),today=new Date(now.getFullYear(),now.getMonth(),now.getDate());let s=new Date(today),e=new Date(today.getFullYear(),today.getMonth(),today.getDate(),23,59,59,999),label="Today's booking report";if(currentReportPeriod==='week'){const day=today.getDay(),diff=day===0?6:day-1;s.setDate(today.getDate()-diff);e=new Date(s.getFullYear(),s.getMonth(),s.getDate()+6,23,59,59,999);label=`Weekly report: ${formatDate(s)} - ${formatDate(e)}`}else if(currentReportPeriod==='month'){s=new Date(today.getFullYear(),selectedReportMonth,1);e=new Date(today.getFullYear(),selectedReportMonth+1,0,23,59,59,999);label=`Monthly report: ${s.toLocaleDateString('en-PH',{month:'long',year:'numeric'})}`}return{s,e,label}}
async function loadStats(){const fd=new FormData();fd.append('action','stats');const res=await fetch('reservations.php',{method:'POST',body:fd});const data=await res.json();if(!data.success)return;stats=data.stats;document.getElementById('stat-total').textContent=stats.total||0;document.getElementById('stat-pending').textContent=stats.pending||0;document.getElementById('stat-confirmed').textContent=stats.confirmed||0;document.getElementById('stat-revenue').textContent=money(stats.revenue||0);document.getElementById('inventory-list').innerHTML=(stats.cottages||[]).map(c=>`<div style="display:flex;justify-content:space-between;padding:10px 0;border-bottom:1px solid #f2f6f6"><span>${c.type}</span><strong>${c.count}</strong></div>`).join('')||'<div class="empty">No cottage data.</div>';document.getElementById('overview-list').innerHTML=`<div style="display:flex;justify-content:space-between;padding:10px 0;border-bottom:1px solid #f2f6f6"><span>Pending</span><strong>${stats.pending||0}</strong></div><div style="display:flex;justify-content:space-between;padding:10px 0;border-bottom:1px solid #f2f6f6"><span>Confirmed</span><strong>${stats.confirmed||0}</strong></div><div style="display:flex;justify-content:space-between;padding:10px 0;border-bottom:1px solid #f2f6f6"><span>Cancelled</span><strong>${stats.cancelled||0}</strong></div><div style="display:flex;justify-content:space-between;padding:10px 0"><span>Today's Bookings</span><strong>${stats.today||0}</strong></div>`;renderCharts()}
async function loadBookings(){const fd=new FormData();fd.append('action','all');const res=await fetch('reservations.php',{method:'POST',body:fd});const data=await res.json();if(!data.success)return;bookings=data.bookings;renderReservations();renderCharts();renderReports()}
async function loadCustomers(search=''){const res=await fetch('auth.php?action=list_users'+(search?`&search=${encodeURIComponent(search)}`:''));const data=await res.json();if(!data.success)return;customers=data.users;renderCustomers()}
async function loadCottages(){const res=await fetch('cottages.php?action=list');const data=await res.json();if(!data.success)return;cottages=data.cottages;renderCottages();fillWalkinOptions()}
async function loadProfile(){const fd=new FormData();fd.append('action','profile');const res=await fetch('auth.php',{method:'POST',body:fd});const data=await res.json();if(!data.success)return;profile=data.profile;document.getElementById('admin-name').textContent=profile.full_name;document.getElementById('settings-name').value=profile.full_name||'';document.getElementById('settings-email').value=profile.email||'';document.getElementById('settings-phone').value=profile.phone||'';document.getElementById('settings-theme').value=profile.display_theme||'teal'}
function populateMonthSelects(){const months=Array.from({length:12},(_,i)=>new Date(new Date().getFullYear(),i,1));document.getElementById('chart-month-select').innerHTML=months.map((d,i)=>`<option value="${i}" ${i===selectedChartMonth?'selected':''}>${d.toLocaleDateString('en-PH',{month:'long',year:'numeric'})}</option>`).join('');document.getElementById('report-month-select').innerHTML=months.map((d,i)=>`<option value="${i}" ${i===selectedReportMonth?'selected':''}>${d.toLocaleDateString('en-PH',{month:'long',year:'numeric'})}</option>`).join('')}
function renderCharts(){const r=chartRange();document.getElementById('chart-label').textContent=r.label;document.getElementById('chart-month-select').style.display=currentChartPeriod==='month'?'block':'none';const filtered=bookings.filter(b=>{const d=whenBooked(b);return d>=r.s&&d<=r.e});const p=filtered.filter(b=>b.status==='pending').length,c=filtered.filter(b=>b.status==='confirmed').length,x=filtered.filter(b=>b.status==='cancelled').length,total=p+c+x;document.getElementById('status-total').textContent=total;let cur=0;const slices=[[p,'#f6b93b'],[c,'#38b46a'],[x,'#f15b5b']].map(([count,color])=>{const start=total?cur/total*360:0;cur+=count;const end=total?cur/total*360:start;return`${color} ${start}deg ${end}deg`});document.getElementById('status-ring').style.background=total?`conic-gradient(${slices.join(',')})`:'#edf4f4';document.getElementById('status-legend').innerHTML=`<div><i style="background:#f6b93b"></i><div><strong>Pending</strong><div>${p} booking${p===1?'':'s'}</div></div></div><div><i style="background:#38b46a"></i><div><strong>Confirmed</strong><div>${c} booking${c===1?'':'s'}</div></div></div><div><i style="background:#f15b5b"></i><div><strong>Cancelled</strong><div>${x} booking${x===1?'':'s'}</div></div></div>`;const counts={Small:0,Medium:0,Large:0,Family:0};filtered.forEach(b=>{if(counts[b.cottage_type]!==undefined)counts[b.cottage_type]+=1});const max=Math.max(...Object.values(counts),1);document.getElementById('type-bars').innerHTML=Object.entries(counts).map(([type,count])=>`<div class="bar"><strong>${count}</strong><div class="fill" style="height:${Math.max(12,(count/max)*180)}px;background:${colors[type]}"></div><label>${type}</label></div>`).join('')}
function setChartPeriod(period,btn){currentChartPeriod=period;document.querySelectorAll('#page-dashboard .filter').forEach(b=>b.classList.remove('active'));if(btn)btn.classList.add('active');renderCharts()} function changeChartMonth(v){selectedChartMonth=Number(v);renderCharts()}
function renderReservations(){const q=(document.getElementById('reservation-search').value||'').toLowerCase();const list=bookings.filter(b=>[b.booking_id,guestName(b),guestEmail(b),b.cottage_name].join(' ').toLowerCase().includes(q));const body=document.getElementById('reservations-tbody');if(!list.length){body.innerHTML='<tr><td colspan="7" class="empty">No reservations found.</td></tr>';return}body.innerHTML=list.map(b=>`<tr><td><strong>${b.booking_id}</strong><br><small>${b.is_walk_in==1?'Walk-in':'Online'} booking</small></td><td><strong>${guestName(b)}</strong><br><small>${guestEmail(b)}<br>${b.guest_phone||''}</small></td><td><strong>${b.cottage_name}</strong><br><small>${b.cottage_type} | ${b.guest_count||1} guests</small></td><td>${formatDate(b.check_in)} ${b.check_in_time||''}<br>${formatDate(b.check_out)} ${b.check_out_time||''}</td><td><strong>${money(b.total_amount)}</strong><br><small>DP: ${money(b.down_payment||0)}</small></td><td><span class="status ${b.status}">${b.status.charAt(0).toUpperCase()+b.status.slice(1)}</span></td><td>${b.status==='pending'?`<button class="action green" type="button" onclick="confirmReservation('${b.booking_id}')">Confirm</button>`:''}${b.status!=='cancelled'?`<button class="action red" type="button" onclick="cancelReservation('${b.booking_id}')">Cancel</button>`:''}</td></tr>`).join('')}
function renderCustomers(){const body=document.getElementById('customers-tbody');if(!customers.length){body.innerHTML='<tr><td colspan="7" class="empty">No customer accounts found.</td></tr>';return}body.innerHTML=customers.map(u=>`<tr><td><strong>${u.full_name}</strong></td><td>${u.email}</td><td>${u.phone||'-'}</td><td><span class="status ${u.is_guest==1?'guest':'active'}">${u.is_guest==1?'Guest Profile':'Registered'}</span></td><td><span class="status ${u.account_status}">${u.account_status.charAt(0).toUpperCase()+u.account_status.slice(1)}</span></td><td>${formatDate(u.created_at)}</td><td><button class="action ${u.account_status==='active'?'red':'green'}" type="button" onclick="toggleCustomerStatus(${u.id},'${u.account_status==='active'?'inactive':'active'}')">${u.account_status==='active'?'Deactivate':'Activate'}</button></td></tr>`).join('')}
function renderCottages(){const body=document.getElementById('cottages-tbody');if(!cottages.length){body.innerHTML='<tr><td colspan="7" class="empty">No cottages found.</td></tr>';return}body.innerHTML=cottages.map(c=>`<tr><td><div class="row"><img class="photo" src="${c.image_url||'assets/cottages/paradise-nook-cottage.jpg'}" alt="${c.name}" onerror="this.src='assets/cottages/paradise-nook-cottage.jpg'"><div><strong>${c.name}</strong><div style="font-size:.76rem;color:#8a9c9c">${c.description||'-'}</div></div></div></td><td>${c.type}</td><td>${c.capacity}</td><td><strong>${money(c.price)}</strong></td><td>${c.pricing_unit}</td><td style="font-size:.8rem;color:#6f8282">${c.amenities||'-'}</td><td><button class="action blue" type="button" onclick="openUpdateCottageModal(${c.id})">Update</button></td></tr>`).join('')}
function renderReports(){const r=reportRange();document.getElementById('report-label').textContent=r.label;document.getElementById('report-month-select').style.display=currentReportPeriod==='month'?'block':'none';const list=bookings.filter(b=>{const d=whenBooked(b);return d>=r.s&&d<=r.e});const confirmed=list.filter(b=>b.status==='confirmed'),cancelled=list.filter(b=>b.status==='cancelled');document.getElementById('rep-total').textContent=list.length;document.getElementById('rep-revenue').textContent=money(confirmed.reduce((s,b)=>s+Number(b.total_amount||0),0));document.getElementById('rep-cancel-rate').textContent=list.length?Math.round(cancelled.length/list.length*100)+'%':'0%';document.getElementById('rep-confirm-rate').textContent=list.length?Math.round(confirmed.length/list.length*100)+'%':'0%';const body=document.getElementById('reports-tbody');if(!list.length){body.innerHTML='<tr><td colspan="7" class="empty">No bookings found for this report period.</td></tr>';return}body.innerHTML=list.map(b=>`<tr><td>${b.booking_id}</td><td><strong>${guestName(b)}</strong><br><small>${guestEmail(b)}</small></td><td>${b.cottage_name}</td><td>${formatDate(b.booked_on||b.created_at)}</td><td>${formatDate(b.check_in)} ${b.check_in_time||''}<br>${formatDate(b.check_out)} ${b.check_out_time||''}</td><td>${money(b.total_amount)}</td><td><span class="status ${b.status}">${b.status.charAt(0).toUpperCase()+b.status.slice(1)}</span></td></tr>`).join('')}
function setReportPeriod(period,btn){currentReportPeriod=period;document.querySelectorAll('#page-reports .filter').forEach(b=>b.classList.remove('active'));if(btn)btn.classList.add('active');renderReports()} function changeReportMonth(v){selectedReportMonth=Number(v);renderReports()}
async function confirmReservation(id){const fd=new FormData();fd.append('action','confirm');fd.append('booking_id',id);const res=await fetch('reservations.php',{method:'POST',body:fd});const data=await res.json();if(!data.success){alert(data.message||'Could not confirm booking.');return}await Promise.all([loadBookings(),loadStats()])}
async function cancelReservation(id){if(!confirm('Cancel this booking?'))return;const fd=new FormData();fd.append('action','cancel');fd.append('booking_id',id);const res=await fetch('reservations.php',{method:'POST',body:fd});const data=await res.json();if(!data.success){alert(data.message||'Could not cancel booking.');return}await Promise.all([loadBookings(),loadStats()])}
async function toggleCustomerStatus(userId,status){const fd=new FormData();fd.append('action','set_user_status');fd.append('user_id',userId);fd.append('status',status);const res=await fetch('auth.php',{method:'POST',body:fd});const data=await res.json();if(!data.success){alert(data.message||'Could not update customer.');return}loadCustomers(document.getElementById('customer-search').value||'')}
function fillWalkinOptions(){const select=document.getElementById('walkin-cottage');if(!select)return;if(!cottages.length){select.innerHTML='<option value="">No cottages available</option>';return}select.innerHTML=cottages.map(c=>`<option value="${c.id}">${c.name} - ${money(c.price)} / ${c.pricing_unit}</option>`).join('')}
function selectedWalkin(){const id=Number(document.getElementById('walkin-cottage').value);return cottages.find(c=>Number(c.id)===id)||null}
function updateWalkinSummary(){const c=selectedWalkin();const totalEl=document.getElementById('walkin-total'),downEl=document.getElementById('walkin-down'),metaEl=document.getElementById('walkin-meta');if(!c){totalEl.textContent='PHP 0';downEl.textContent='PHP 0';metaEl.textContent='Choose a cottage and dates to compute the walk-in total.';return}const start=new Date(document.getElementById('walkin-checkin').value),end=new Date(document.getElementById('walkin-checkout').value);let units=Math.max(1,Math.round((end-start)/86400000));if(c.pricing_unit==='event')units=1;const total=Number(c.price)*units;totalEl.textContent=money(total);downEl.textContent=money(total*.3);metaEl.textContent=`${units} ${c.pricing_unit}${units===1?'':'s'} x ${money(c.price)} | Capacity ${c.capacity} guests`}
function openWalkInModal(){fillWalkinOptions();const today=new Date(),next=new Date(today);next.setDate(next.getDate()+1);document.getElementById('walkin-checkin').value=today.toISOString().split('T')[0];document.getElementById('walkin-checkout').value=next.toISOString().split('T')[0];document.getElementById('walkin-checkin').min=today.toISOString().split('T')[0];document.getElementById('walkin-checkout').min=next.toISOString().split('T')[0];document.getElementById('walkin-checkin-time').value='14:00';document.getElementById('walkin-checkout-time').value='12:00';document.getElementById('walkin-name').value='';document.getElementById('walkin-phone').value='';document.getElementById('walkin-email').value='';document.getElementById('walkin-count').value='1';document.getElementById('walkin-error').style.display='none';document.getElementById('walkin-success').style.display='none';updateWalkinSummary();openModal('walkin')}
async function submitWalkIn(){const err=document.getElementById('walkin-error'),ok=document.getElementById('walkin-success');err.style.display='none';ok.style.display='none';const c=selectedWalkin();if(!c){err.textContent='Select a cottage first.';err.style.display='block';return}const fd=new FormData();fd.append('action','walk_in_book');fd.append('cottage_id',c.id);fd.append('guest_name',document.getElementById('walkin-name').value);fd.append('guest_phone',document.getElementById('walkin-phone').value);fd.append('guest_email',document.getElementById('walkin-email').value);fd.append('guest_count',document.getElementById('walkin-count').value);fd.append('check_in',document.getElementById('walkin-checkin').value);fd.append('check_in_time',document.getElementById('walkin-checkin-time').value);fd.append('check_out',document.getElementById('walkin-checkout').value);fd.append('check_out_time',document.getElementById('walkin-checkout-time').value);const res=await fetch('reservations.php',{method:'POST',body:fd});const data=await res.json();if(!data.success){err.textContent=data.message||'Could not create walk-in booking.';err.style.display='block';return}ok.textContent=`Walk-in booking created. Booking ID: ${data.booking_id}`;ok.style.display='block';await Promise.all([loadBookings(),loadStats()])}
function openAddCottageModal(){['add-name','add-capacity','add-price','add-image','add-description','add-amenities'].forEach(id=>document.getElementById(id).value='');document.getElementById('add-type').value='Small';document.getElementById('add-unit').value='day';document.getElementById('add-cottage-error').style.display='none';openModal('cottage-add')}
async function submitAddCottage(){const err=document.getElementById('add-cottage-error');err.style.display='none';const fd=new FormData();fd.append('action','add');fd.append('name',document.getElementById('add-name').value);fd.append('description',document.getElementById('add-description').value);fd.append('type',document.getElementById('add-type').value);fd.append('capacity',document.getElementById('add-capacity').value);fd.append('price',document.getElementById('add-price').value);fd.append('pricing_unit',document.getElementById('add-unit').value);fd.append('amenities',document.getElementById('add-amenities').value);fd.append('image_url',document.getElementById('add-image').value);const res=await fetch('cottages.php',{method:'POST',body:fd});const data=await res.json();if(!data.success){err.textContent=data.message||'Could not add cottage.';err.style.display='block';return}closeModal('cottage-add');await Promise.all([loadCottages(),loadStats()]);showPage('cottages')}
function openUpdateCottageModal(id){const c=cottages.find(item=>Number(item.id)===Number(id));if(!c)return;updatingCottageId=Number(id);document.getElementById('update-name').value=c.name||'';document.getElementById('update-price').value=c.price||'';document.getElementById('update-unit').value=c.pricing_unit||'day';document.getElementById('update-amenities').value=c.amenities||'';document.getElementById('update-cottage-error').style.display='none';openModal('cottage-update')}
async function submitUpdateCottage(){const err=document.getElementById('update-cottage-error');err.style.display='none';const c=cottages.find(item=>Number(item.id)===Number(updatingCottageId));if(!c){err.textContent='Cottage record not found.';err.style.display='block';return}const fd=new FormData();fd.append('action','update');fd.append('id',c.id);fd.append('name',c.name);fd.append('description',c.description||'');fd.append('type',c.type);fd.append('capacity',c.capacity);fd.append('price',document.getElementById('update-price').value);fd.append('pricing_unit',document.getElementById('update-unit').value);fd.append('amenities',document.getElementById('update-amenities').value);fd.append('image_url',c.image_url||'');fd.append('is_available',c.is_available||1);const res=await fetch('cottages.php',{method:'POST',body:fd});const data=await res.json();if(!data.success){err.textContent=data.message||'Could not update cottage.';err.style.display='block';return}closeModal('cottage-update');await Promise.all([loadCottages(),loadStats()])}
async function saveAdminProfile(){const err=document.getElementById('settings-error'),ok=document.getElementById('settings-success');err.style.display='none';ok.style.display='none';const fd=new FormData();fd.append('action','update_profile');fd.append('full_name',document.getElementById('settings-name').value);fd.append('phone',document.getElementById('settings-phone').value);fd.append('display_theme',document.getElementById('settings-theme').value);const res=await fetch('auth.php',{method:'POST',body:fd});const data=await res.json();if(!data.success){err.textContent=data.message||'Could not update profile.';err.style.display='block';return}profile={...(profile||{}),...data.profile};document.getElementById('admin-name').textContent=data.profile.full_name;ok.textContent='Admin profile updated.';ok.style.display='block'}
async function changeAdminPassword(){const err=document.getElementById('password-error'),ok=document.getElementById('password-success');err.style.display='none';ok.style.display='none';const fd=new FormData();fd.append('action','change_password');fd.append('current_password',document.getElementById('settings-current-password').value);fd.append('new_password',document.getElementById('settings-new-password').value);fd.append('confirm_password',document.getElementById('settings-confirm-password').value);const res=await fetch('auth.php',{method:'POST',body:fd});const data=await res.json();if(!data.success){err.textContent=data.message||'Could not change password.';err.style.display='block';return}['settings-current-password','settings-new-password','settings-confirm-password'].forEach(id=>document.getElementById(id).value='');ok.textContent='Password changed successfully.';ok.style.display='block'}
async function logout(){const fd=new FormData();fd.append('action','logout');await fetch('auth.php',{method:'POST',body:fd});window.location.href='index.php'}
document.querySelectorAll('.overlay').forEach(el=>el.addEventListener('click',e=>{if(e.target===el)el.classList.remove('active')}));
['walkin-cottage','walkin-count','walkin-checkin','walkin-checkout','walkin-checkin-time','walkin-checkout-time'].forEach(id=>document.addEventListener('change',e=>{if(e.target&&e.target.id===id){if(id==='walkin-checkin'){const v=document.getElementById('walkin-checkin').value;if(v){const next=new Date(v);next.setDate(next.getDate()+1);document.getElementById('walkin-checkout').min=next.toISOString().split('T')[0];if(document.getElementById('walkin-checkout').value<=v){document.getElementById('walkin-checkout').value=next.toISOString().split('T')[0]}}}updateWalkinSummary()}}));
async function boot(){populateMonthSelects();await Promise.allSettled([loadStats(),loadBookings(),loadCustomers(),loadCottages(),loadProfile()]);renderCharts();renderReports();renderCustomers();renderCottages()}
boot();
</script>
</body>
</html>
